import{_ as a,o as t,c as i,ae as o}from"./chunks/framework.B2ul6ABY.js";const h=JSON.parse('{"title":"Implementation Plan","description":"","frontmatter":{},"headers":[],"relativePath":"historical/2026-pre-consolidation/12-implementation-plan.md","filePath":"historical/2026-pre-consolidation/12-implementation-plan.md"}'),r={name:"historical/2026-pre-consolidation/12-implementation-plan.md"};function l(n,e,c,s,d,u){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="implementation-plan" tabindex="-1">Implementation Plan <a class="header-anchor" href="#implementation-plan" aria-label="Permalink to &quot;Implementation Plan&quot;">​</a></h1><p>This plan stages Saivage v3 implementation from a verifiable local kernel to the full autonomous control room. Each stage has clear bounds and acceptance criteria so the project can ship usable slices without blurring architecture decisions.</p><p>The implementation target is the system defined by:</p><ul><li><code>docs/design/card-model.md</code> for card semantics and planner/reviewer gates.</li><li><code>docs/design/agents.md</code> for agent roles and tool boundaries.</li><li><code>docs/design/runtime.md</code> for dispatch, recovery, locking, and processes.</li><li><code>docs/design/security.md</code> for content supervision and access rules.</li><li><code>docs/design/configuration.md</code> for configuration and provider routing.</li><li><code>docs/design/server-api.md</code> for HTTP/WebSocket surface.</li><li><code>docs/design/data-model.md</code> for schemas and file layout.</li><li><code>docs/design/ux-design.md</code> for the web UI.</li></ul><hr><h2 id="delivery-principles" tabindex="-1">Delivery Principles <a class="header-anchor" href="#delivery-principles" aria-label="Permalink to &quot;Delivery Principles&quot;">​</a></h2><ul><li>Build from the persistence layer upward. Every stage should leave inspectable files under <code>.saivage/</code> and <code>.saivage-work/</code>.</li><li>Keep the runtime deterministic before adding LLM behavior. Card transitions, queues, locking, and recovery should be testable without real model calls.</li><li>Treat agents as replaceable adapters. The runtime owns sequencing; agents return structured results.</li><li>Prefer narrow vertical slices over broad scaffolding. Each stage must demonstrate one working path end to end.</li><li>Do not add parallel planner/executor/reviewer dispatch in the initial implementation.</li></ul><hr><h2 id="stage-0-—-project-skeleton-and-contracts" tabindex="-1">Stage 0 — Project Skeleton and Contracts <a class="header-anchor" href="#stage-0-—-project-skeleton-and-contracts" aria-label="Permalink to &quot;Stage 0 — Project Skeleton and Contracts&quot;">​</a></h2><h3 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Create the application repository structure.</li><li>Add TypeScript project configuration, linting, formatting, and test runner.</li><li>Define shared schema/types package for cards, notes, diaries, runtime state, process records, config, provider/account/model routing, and API envelopes.</li><li>Add schema validation using a runtime validator.</li><li>Add fixture projects under <code>fixtures/</code> for tests.</li></ul><h3 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>No LLM provider calls.</li><li>No web UI beyond placeholder build wiring.</li><li>No external MCP server support.</li></ul><h3 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li><code>npm test</code> runs schema/unit tests successfully.</li><li><code>npm run typecheck</code> passes.</li><li>All records from <code>docs/design/data-model.md</code> have corresponding TypeScript types and validators.</li><li>Fixture JSON records round-trip through validators without data loss.</li><li>Invalid fixture records fail validation with useful error messages.</li></ul><hr><h2 id="stage-1-—-local-persistence-and-card-store" tabindex="-1">Stage 1 — Local Persistence and Card Store <a class="header-anchor" href="#stage-1-—-local-persistence-and-card-store" aria-label="Permalink to &quot;Stage 1 — Local Persistence and Card Store&quot;">​</a></h2><h3 id="scope-1" tabindex="-1">Scope <a class="header-anchor" href="#scope-1" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Implement project discovery using <code>.saivage/saivage.json</code>.</li><li>Initialize a project-local <code>.saivage/</code> and <code>.saivage-work/</code> tree.</li><li>Implement card CRUD through a <code>CardStore</code> service.</li><li>Implement note logs, plan diary append, review assessment append, artifact and attachment registration.</li><li>Enforce hierarchy rules from <code>docs/design/card-model.md</code>.</li><li>Implement atomic writes for metadata files.</li></ul><h3 id="out-of-scope-1" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope-1" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>No agent execution.</li><li>No HTTP API writes except optional internal smoke endpoint.</li><li>No cleanup command beyond explicit test helpers.</li></ul><h3 id="acceptance-criteria-1" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-1" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>A new project initializes the file tree from <code>docs/design/data-model.md</code>.</li><li>Creating a project card auto-creates no duplicate project roots.</li><li>Activating any project/goal card auto-creates exactly one plan card.</li><li>Terminal cards cannot have children.</li><li><code>depends_on</code> and computed <code>blocks</code> remain consistent after card updates and deletes.</li><li>Notes are mutable only until marked handled.</li><li>All card mutations are covered by unit tests, including invalid hierarchy moves and dependency cycles.</li></ul><hr><h2 id="stage-2-—-runtime-kernel-without-llms" tabindex="-1">Stage 2 — Runtime Kernel Without LLMs <a class="header-anchor" href="#stage-2-—-runtime-kernel-without-llms" aria-label="Permalink to &quot;Stage 2 — Runtime Kernel Without LLMs&quot;">​</a></h2><h3 id="scope-2" tabindex="-1">Scope <a class="header-anchor" href="#scope-2" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Implement runtime state persistence at <code>.saivage/runtime/state.json</code>.</li><li>Implement exclusive lock at <code>.saivage-work/tmp/runtime/runtime.lock</code>.</li><li>Implement startup, stale lock detection, graceful shutdown, and crash recovery.</li><li>Implement deterministic queue selection by <code>depends_on</code>, status, and priority.</li><li>Implement a fake agent adapter that returns scripted planner, executor, and reviewer results from fixtures.</li><li>Implement global pause/resume.</li></ul><h3 id="out-of-scope-2" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope-2" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>No real model provider integration.</li><li>No shell/process execution.</li><li>No web UI.</li></ul><h3 id="acceptance-criteria-2" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-2" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>A fixture goal can move from <code>backlog</code> to <code>done</code> through planner, executor, and reviewer fixture results.</li><li>A reviewer failure re-invokes the planner and correction cards run before the next review.</li><li>A failed terminal card re-invokes the parent planner.</li><li>A second runtime instance cannot acquire the lock while the first is alive.</li><li>Stale locks are removed only when the PID is dead or older than the configured age bound.</li><li>After simulated crash, <code>active</code> and <code>running</code> cards are reset to <code>backlog</code> and the runtime can resume.</li></ul><hr><h2 id="stage-3-—-process-execution-and-artifacts" tabindex="-1">Stage 3 — Process Execution and Artifacts <a class="header-anchor" href="#stage-3-—-process-execution-and-artifacts" aria-label="Permalink to &quot;Stage 3 — Process Execution and Artifacts&quot;">​</a></h2><h3 id="scope-3" tabindex="-1">Scope <a class="header-anchor" href="#scope-3" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Implement process registry and async command execution.</li><li>Implement <code>start_process</code>, <code>wait_process</code>, <code>start_and_wait</code>, <code>tail_output</code>, <code>kill_process</code>, and <code>list_processes</code>.</li><li>Persist process metadata under <code>.saivage/runtime/</code> and output under <code>.saivage-work/processes/</code>.</li><li>Register artifacts and attachments produced by executor work.</li><li>Add safe cleanup for <code>.saivage-work/tmp/stash/</code> and card tmp files.</li></ul><h3 id="out-of-scope-3" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope-3" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>No arbitrary remote command execution.</li><li>No automatic cleanup of retained artifacts.</li><li>No model-driven executor yet; use fake/scripted executor harness.</li></ul><h3 id="acceptance-criteria-3" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-3" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>Long-running commands can be started, tailed, waited on, and killed.</li><li>Timed-out waits do not kill the process.</li><li>Process output survives runtime restart.</li><li>A terminal card can produce retained and working artifacts, and the card record points to the correct files.</li><li>Cleanup never removes retained artifacts, attachments, download reviews, or quarantine metadata.</li></ul><hr><h2 id="stage-4-—-agent-adapter-and-model-routing" tabindex="-1">Stage 4 — Agent Adapter and Model Routing <a class="header-anchor" href="#stage-4-—-agent-adapter-and-model-routing" aria-label="Permalink to &quot;Stage 4 — Agent Adapter and Model Routing&quot;">​</a></h2><h3 id="scope-4" tabindex="-1">Scope <a class="header-anchor" href="#scope-4" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Implement provider abstraction and model router from <code>docs/design/configuration.md</code>.</li><li>Load per-role ordered model lists, provider capabilities, provider priorities, account priorities, and routing profiles.</li><li>Resolve each agent role to an ordered <code>provider/account/model</code> candidate chain.</li><li>Implement provider/account cooldown so a failing provider is skipped before the router advances to the next model.</li><li>Implement structured result parsing for planner, executor, and reviewer responses.</li><li>Implement agent session/message persistence.</li><li>Implement context compaction and max-compaction termination.</li><li>Implement agent invocation recovery wrapper.</li></ul><h3 id="out-of-scope-4" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope-4" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>No web UI conversation inspector yet.</li><li>No external MCP servers.</li><li>No Telegram.</li></ul><h3 id="acceptance-criteria-4" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-4" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>Planner can create valid card mutations from a model response.</li><li>Executor can complete a terminal card using runtime tools only.</li><li>Reviewer can pass/fail a goal and append assessment to the plan diary.</li><li>Invalid or partial model output produces a recoverable invocation failure, not corrupted card state.</li><li>Role-to-model routing first chooses a configured model, then tries eligible providers/accounts for that model in priority order.</li><li>If a provider/account fails, the router tries the next eligible provider/account for the same model before advancing to the next configured model.</li><li>Failed provider/account/model candidates respect recovery delays and are retried only after their cooldown expires.</li><li>Compaction triggers at the configured threshold and preserves enough state for recovery.</li></ul><hr><h2 id="stage-5-—-security-and-content-supervision" tabindex="-1">Stage 5 — Security and Content Supervision <a class="header-anchor" href="#stage-5-—-security-and-content-supervision" aria-label="Permalink to &quot;Stage 5 — Security and Content Supervision&quot;">​</a></h2><h3 id="scope-5" tabindex="-1">Scope <a class="header-anchor" href="#scope-5" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Implement prompt injection scanner with heuristic and LLM-assisted layers.</li><li>Implement quarantine storage under <code>.saivage-work/quarantine/</code> with metadata under <code>.saivage/supervision/</code>.</li><li>Implement sensitive file blocking and secret redaction.</li><li>Implement write territory warnings.</li><li>Implement stash for oversized tool results.</li></ul><h3 id="out-of-scope-5" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope-5" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>No enterprise policy engine.</li><li>No automatic remediation of blocked content.</li></ul><h3 id="acceptance-criteria-5" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-5" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>Obvious injection strings are blocked or escalated to LLM scan.</li><li>Blocked content is stored in quarantine and never injected into an agent context.</li><li>Agents cannot read <code>.saivage/auth-profiles.json</code>.</li><li>Config secrets are redacted through APIs and agent-readable config views.</li><li><code>read_stash</code> rejects path traversal and only reads stash files.</li><li>Territory violations are logged as warnings without blocking normal safe writes.</li></ul><hr><h2 id="stage-6-—-http-api-and-websocket-runtime-feed" tabindex="-1">Stage 6 — HTTP API and WebSocket Runtime Feed <a class="header-anchor" href="#stage-6-—-http-api-and-websocket-runtime-feed" aria-label="Permalink to &quot;Stage 6 — HTTP API and WebSocket Runtime Feed&quot;">​</a></h2><h3 id="scope-6" tabindex="-1">Scope <a class="header-anchor" href="#scope-6" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Implement Fastify server and <code>/health</code>.</li><li>Implement API authentication using <code>SAIVAGE_API_TOKEN</code>.</li><li>Implement card, runtime, agent conversation, config, notes, chat, files, and debug endpoints from <code>docs/design/server-api.md</code>.</li><li>Implement WebSocket auth and JSON event envelopes.</li><li>Wire runtime event bus to WebSocket clients.</li></ul><h3 id="out-of-scope-6" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope-6" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>No full web UI yet.</li><li>No public multi-tenant auth.</li></ul><h3 id="acceptance-criteria-6" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-6" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li><code>/health</code> works without auth and reports version/project/runtime.</li><li>All <code>/api/*</code> endpoints reject unauthenticated requests.</li><li>WebSocket rejects invalid auth with code <code>1008</code>.</li><li>File APIs reject path traversal, sensitive files, and files above the size limit.</li><li>Runtime events appear on connected WebSocket clients using the documented envelope.</li><li>API tests cover success and failure cases for each endpoint group.</li></ul><hr><h2 id="stage-7-—-analyst-chat-and-basic-control-plane" tabindex="-1">Stage 7 — Analyst Chat and Basic Control Plane <a class="header-anchor" href="#stage-7-—-analyst-chat-and-basic-control-plane" aria-label="Permalink to &quot;Stage 7 — Analyst Chat and Basic Control Plane&quot;">​</a></h2><h3 id="scope-7" tabindex="-1">Scope <a class="header-anchor" href="#scope-7" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Implement analyst agent sessions over API/WebSocket.</li><li>Implement analyst tools for card management, notes, runtime control, process inspection, and process kill.</li><li>Add action previews for destructive operations.</li><li>Persist analyst conversations.</li></ul><h3 id="out-of-scope-7" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope-7" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>No Telegram yet.</li><li>No rich web UI beyond minimal chat/client harness.</li></ul><h3 id="acceptance-criteria-7" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-7" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>User can create a goal via analyst chat and inspect the resulting card tree.</li><li>User can pause/resume runtime through analyst chat.</li><li>User can add an unhandled directive to a running/backlog card.</li><li>Destructive actions require a structured preview/confirmation step.</li><li>Analyst cannot directly perform terminal task work; task work still goes through executor/runtime flow.</li></ul><hr><h2 id="stage-8-—-web-control-room" tabindex="-1">Stage 8 — Web Control Room <a class="header-anchor" href="#stage-8-—-web-control-room" aria-label="Permalink to &quot;Stage 8 — Web Control Room&quot;">​</a></h2><h3 id="scope-8" tabindex="-1">Scope <a class="header-anchor" href="#scope-8" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Implement the Vue SPA from <code>docs/design/ux-design.md</code>.</li><li>Build Dashboard, Cards, Agents, Files, and Debug sections.</li><li>Render tree, board, leaderboard, and timeline views over the same card model.</li><li>Render attachments inline in the web UI only.</li><li>Add runtime status, queue, process, notes, and event views.</li></ul><h3 id="out-of-scope-8" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope-8" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>No advanced dashboard customization.</li><li>No mobile-specific workflow beyond responsive usability.</li></ul><h3 id="acceptance-criteria-8" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-8" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>Dashboard shows analyst chat and live runtime status.</li><li>Cards section can inspect project, goal, plan, and terminal cards.</li><li>Plan diary and reviewer assessments render from structured JSON.</li><li>Files section separates <code>.saivage/</code> metadata from <code>.saivage-work/</code> outputs and respects file API protections.</li><li>Debug section shows runtime state, errors, and timeline.</li><li>UI state updates from WebSocket events without manual refresh.</li></ul><hr><h2 id="stage-9-—-external-integrations" tabindex="-1">Stage 9 — External Integrations <a class="header-anchor" href="#stage-9-—-external-integrations" aria-label="Permalink to &quot;Stage 9 — External Integrations&quot;">​</a></h2><h3 id="scope-9" tabindex="-1">Scope <a class="header-anchor" href="#scope-9" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Implement external MCP server configuration and lifecycle.</li><li>Implement Telegram bot channel with allowed user filtering, Markdown-to-HTML conversion, message splitting, and per-chat analyst sessions.</li><li>Implement OAuth auth profile loading and refresh for providers that need it.</li><li>Implement notification filters and channel routing.</li></ul><h3 id="out-of-scope-9" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope-9" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>No plugin marketplace.</li><li>No group chat collaboration model beyond allowed user IDs.</li></ul><h3 id="acceptance-criteria-9" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-9" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>Configured stdio and SSE MCP servers start, stop, and report health.</li><li>Disabled MCP servers are skipped.</li><li>Telegram ignores unauthorized users.</li><li>Long Telegram messages are split under the 4096-character limit.</li><li>Telegram notifications link to cards and mention attachments without rendering them inline.</li><li>OAuth profiles are stored with mode <code>0600</code> and are never exposed via API or agent file access.</li></ul><hr><h2 id="stage-10-—-hardening-and-release-candidate" tabindex="-1">Stage 10 — Hardening and Release Candidate <a class="header-anchor" href="#stage-10-—-hardening-and-release-candidate" aria-label="Permalink to &quot;Stage 10 — Hardening and Release Candidate&quot;">​</a></h2><h3 id="scope-10" tabindex="-1">Scope <a class="header-anchor" href="#scope-10" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Add end-to-end tests covering a realistic project lifecycle.</li><li>Add observability for errors, event timeline, agent recovery, and process execution.</li><li>Add packaging/install documentation.</li><li>Run security review for file access, API auth, token redaction, and prompt-injection handling.</li><li>Produce release checklist and operator runbook.</li></ul><h3 id="out-of-scope-10" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope-10" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>No new product surface unless required by release-blocking bugs.</li><li>No major architecture changes without updating the design docs first.</li></ul><h3 id="acceptance-criteria-10" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-10" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>End-to-end test initializes a project, creates a goal, runs planner, executor, reviewer, produces artifacts, and displays results via API.</li><li>Crash/restart test resumes safely without duplicate plan cards or corrupted runtime state.</li><li>Security tests cover auth failures, path traversal, secret redaction, quarantine, and stash access.</li><li>Documentation includes install, configuration, operation, backup, and troubleshooting paths.</li><li>A release candidate can be installed and run from a clean checkout with only documented prerequisites.</li></ul><hr><h2 id="cross-stage-acceptance-gates" tabindex="-1">Cross-Stage Acceptance Gates <a class="header-anchor" href="#cross-stage-acceptance-gates" aria-label="Permalink to &quot;Cross-Stage Acceptance Gates&quot;">​</a></h2><p>These gates apply before moving to the next stage:</p><ul><li><strong>State integrity</strong>: No stage may write state outside <code>.saivage/</code> and <code>.saivage-work/</code> except explicit project source edits by executors.</li><li><strong>Card invariants</strong>: Project singleton, one plan per goal, terminal-card leaf rule, dependency consistency, and reviewer gate must remain enforced.</li><li><strong>Recovery</strong>: Interrupted work must leave enough persisted state for the runtime to resume or report a precise failure.</li><li><strong>Security</strong>: Sensitive files remain blocked and secrets remain redacted in all user-facing and agent-facing surfaces.</li><li><strong>Tests</strong>: New behavior must include automated coverage at the narrowest useful level, with end-to-end coverage for runtime flows.</li></ul><hr><h2 id="initial-milestone-cut" tabindex="-1">Initial Milestone Cut <a class="header-anchor" href="#initial-milestone-cut" aria-label="Permalink to &quot;Initial Milestone Cut&quot;">​</a></h2><p>The first usable milestone is <strong>Stage 0 through Stage 3</strong>:</p><ul><li>Local project init.</li><li>Valid card tree persistence.</li><li>Deterministic runtime dispatch using fake agents.</li><li>Real process execution and artifact registration.</li></ul><p>This milestone proves the core non-LLM runtime before adding model variability. After that, Stage 4 can integrate real agents with much less uncertainty.</p>',104)])])}const m=a(r,[["render",l]]);export{h as __pageData,m as default};
